        // ==================== KNOWN QUOTE CURRENCIES (for Gemini/Yobit parsing) ====================
        const KNOWN_QUOTES = [
            'USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY', 'KRW',
            'AUD', 'CAD', 'CHF', 'RUR', 'RUB', 'INR', 'TRY', 'BRL', 'IDR', 'DAI', 'SGD', 'PLN', 'UAH'
        ];
        // Sort by length descending so "USDT" matches before "USD"
        KNOWN_QUOTES.sort((a, b) => b.length - a.length);

        function parsePairSymbol(rawSymbol) {
            const sym = (rawSymbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            if (!sym) return null;
            for (const quote of KNOWN_QUOTES) {
                if (sym.endsWith(quote) && sym.length > quote.length) {
                    const base = sym.slice(0, sym.length - quote.length);
                    if (base.length >= 1 && base !== quote) {
                        return { base, target: quote };
                    }
                }
            }
            // Fallback: try splitting on common separators
            const parts = sym.split(/[-_/]/);
            if (parts.length >= 2 && parts[0] && parts[1]) {
                return { base: parts[0], target: parts[1] };
            }
            // Last resort: assume last 3-4 chars are quote
            if (sym.length > 4) {
                const target = sym.slice(-4);
                const base = sym.slice(0, -4);
                if (KNOWN_QUOTES.includes(target)) return { base, target };
            }
            if (sym.length > 3) {
                const target = sym.slice(-3);
                const base = sym.slice(0, -3);
                if (KNOWN_QUOTES.includes(target)) return { base, target };
            }
            return null;
        }

        // ==================== EXCHANGE DEFINITIONS ====================
        const exchangeDefs = [
