                    }
                    default:
                        pairs = [];
                }
                // Post-filter: remove pairs where base==target or price is absurd
                pairs = pairs.filter(p => p && p.base && p.target && p.base !== p.target && p.price > 0 && p.price <
                    1e15);
                ex.pairs = pairs;
                ex.status = 'online';
                log(`${ex.name}: ${ex.pairs.length} pairs`, 'success');
            } catch (e) {
                if (defKey === 'pumpfun') {
                    log('Pump.fun direct failed, trying fallback...', 'warning');
                    try {
                        const fbResp = await fetch(getProxiedUrl(
                            'https://api.dexscreener.com/latest/dex/search?q=SOL'));
                        const fbData = await fbResp.json();
                        const fbPairs = (fbData?.pairs || []).slice(0, 400).map(p => {
                            const price = parseFloat(p.priceUsd) || 0,
                                liq = p.liquidity?.usd || 0;
                            const spread = liq > 0 ? Math.max(0.003, Math.min(0.05, 5000 / liq)) : 0.03;
                            return { base: p.baseToken?.symbol || 'UNKNOWN', target: p.quoteToken?.symbol ||
                                    'ETH', price, volume: p.volume?.h24 || 0, liquidity: liq, bidPrice: price *
                                    (1 - spread / 2), askPrice: price * (1 + spread / 2),
                                exchange: 'pumpfun_fallback', exchangeType: 'dex' };
                        }).filter(p => p.base !== 'UNKNOWN' && p.price > 0);
                        ex.pairs = fbPairs;
                        ex.status = 'online';
                        log(`Pump.fun fallback: ${ex.pairs.length} pairs`, 'success');
                        return;
                    } catch (fbErr) { log(`Fallback also failed: ${fbErr.message}`, 'error'); }
                }
                ex.status = 'offline';
                ex.pairs = [];
                log(`${ex.name}: ${e.message}`, 'error');
            }
        }

        // ==================== INIT ====================
        async function initSystem() {
            log('🎰 Initializing all exchanges (with proxy + fixed parsers)...');
            updateStatus('🔄 LOADING...');
            playSpin();
            UI.checkProxyPlaceholder();
            await Promise.allSettled(exchangeDefs.map(d => loadApi(d.key)));
            State.allPairs = Object.values(State.exchanges).flatMap(e => e.pairs);
            State.userCoins.forEach(c => {
                State.allPairs.push({ base: c.symbol, target: 'USDT', price: c.price, volume: c.liq * 0.3,
                    liquidity: c.liq, bidPrice: c.price * 0.95, askPrice: c.price * 1.05, exchange: 'QUANTM_DEX',
                    exchangeType: 'dex' });
            });
            State.stats.totalPairs = State.allPairs.length;
            updateIntraExCheckboxes();
            buildGraph();
            buildTriangles();
            displayLowValue();
            updateExchangeDisplay();
            updateStats();
            const online = Object.values(State.exchanges).filter(e => e.status === 'online').length;
            if (online > 0) {
                document.getElementById('scanBtn').disabled = false;
                updateStatus(`✅ READY · ${online}/${exchangeDefs.length} online · ${State.stats.totalPairs} pairs`);
                log('System ready.', 'success');
            } else { updateStatus('❌ NO EXCHANGES ONLINE'); }
        }

        function updateStatus(msg) { document.getElementById('mainStatus').innerHTML = msg; }

        // ==================== GRAPH & VISUAL (FIXED RATE CONVENTION) ====================
        function getGraphPairs() {
            const mode = document.getElementById('arbMode').value;
            if (mode === 'intra') return [...State.selectedIntraExchanges].flatMap(k => State.exchanges[k]
            ?.pairs || []);
            return Object.values(State.exchanges).filter(e => e.status === 'online' && e.type !== 'info').flatMap(
                e => e.pairs);
        }

        function applyWsCache(pair) {
            const cache = State.wsTickers[pair.exchange];
            if (cache) {
                const key = `${pair.base}${pair.target}`.toUpperCase();
                const tick = cache[key];
                if (tick) { return { ...pair, bidPrice: tick.bid || pair.bidPrice, askPrice: tick.ask || pair
                        .askPrice }; }
            }
            return pair;
        }

        function sanitizeRate(r) {
            if (!isFinite(r) || r <= 0) return 0;
            if (r > 1e12) return 1e12;
            if (r < 1e-15) return 1e-15;
            return r;
        }

        function buildGraph() {
            State.graph = {};
            const pairs = getGraphPairs().map(applyWsCache);
            pairs.forEach(p => {
                if (p.liquidity < 50) return;
                if (!p.base || !p.target || p.base === p.target) return;
                if (!State.graph[p.base]) State.graph[p.base] = {};
                if (!State.graph[p.target]) State.graph[p.target] = {};
                // FIXED RATE CONVENTION:
                // base → target: sell base, receive target → use bidPrice
                // target → base: buy base with target → use 1/askPrice
                const rateBaseToTarget = sanitizeRate(p.bidPrice);
                const rateTargetToBase = sanitizeRate(1 / p.askPrice);
                if (rateBaseToTarget > 0) {
                    State.graph[p.base][p.target] = { rate: rateBaseToTarget, weight: -Math.log(rateBaseToTarget),
                        volume: p.volume, liquidity: p.liquidity, exchange: p.exchange, exchangeType: p
                        .exchangeType };
                }
                if (rateTargetToBase > 0) {
                    State.graph[p.target][p.base] = { rate: rateTargetToBase, weight: -Math.log(rateTargetToBase),
                        volume: p.volume, liquidity: p.liquidity, exchange: p.exchange, exchangeType: p
                        .exchangeType };
                }
            });
            State.stats.graphNodes = Object.keys(State.graph).length;
            State.stats.graphEdges = Object.values(State.graph).reduce((s, o) => s + Object.keys(o).length, 0);
        }

        function buildTriangles() {
            State.triangles = [];
            const nodes = Object.keys(State.graph);
            for (let i = 0; i < Math.min(nodes.length, 120); i++) {
                const A = nodes[i];
                const nA = Object.keys(State.graph[A] || {});
                for (const B of nA) {
                    const nB = Object.keys(State.graph[B] || {});
                    for (const C of nB)
                        if (State.graph[C]?.[A]) State.triangles.push([A, B, C]);
                }
            }
            State.stats.triangleCount = State.triangles.length;
        }

