        async function handleRequest(request) {
        const url = new URL(request.url);
        const targetUrl = url.searchParams.get('url');
        if (!targetUrl) {
        return new Response(JSON.stringify({error:'Missing ?url= parameter'}), {
        status:400, headers:{'Content-Type':'application/json','Access-Control-Allow-Origin':'*'}
        });
        }
        // Validate target URL is an allowed exchange
        const allowedDomains = ['api.binance.com','api.kucoin.com','api.kraken.com','api.gateio.ws',
        'api.mexc.com','api.bybit.com','api.huobi.pro','api.poloniex.com','yobit.net',
        'api.bitstamp.net','api.bittrex.com','api.coingecko.com','api.dexscreener.com',
        'api.exchange.coinbase.com','www.okx.com','api.gemini.com','ascendex.com',
        'openapi.digifinex.com','api.crypto.com','indodax.com','api.coinlore.net',
        'api.coinpaprika.com','api.coincap.io','frontend-api.pump.fun'];
        const targetHost = new URL(targetUrl).hostname;
        if (!allowedDomains.some(d => targetHost.endsWith(d))) {
        return new Response(JSON.stringify({error:'Domain not allowed'}), {
        status:403, headers:{'Content-Type':'application/json','Access-Control-Allow-Origin':'*'}
        });
        }
        // Forward request with CORS headers
        const response = await fetch(targetUrl, {
        method: request.method,
        headers: { 'User-Agent': 'QuanTM-FOAM/22.4' }
        });
        const corsHeaders = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
        };
        if (request.method === 'OPTIONS') {
        return new Response(null, { status: 204, headers: corsHeaders });
        }
        const body = await response.text();
        return new Response(body, { status: response.status, headers: corsHeaders });
        }
