        // Built-in public CORS proxy list (rotates automatically)
        const BUILTIN_PROXIES = [
            'https://corsproxy.io/?',
            'https://api.allorigins.win/raw?url=',
            'https://cors-anywhere.herokuapp.com/',
            'https://proxy.cors.sh/'
        ];
        let currentProxyIndex = 0;

        function getEffectiveProxyUrl() {
            if (State.proxyMode === 'custom') {
                const custom = (document.getElementById('corsProxyUrl')?.value || '').trim();
                if (custom && !custom.includes('your-worker') && !custom.includes('placeholder')) {
                    return custom;
                }
                // fallback to builtin if custom is placeholder
            }
            return BUILTIN_PROXIES[currentProxyIndex];
        }

        function rotateProxy() {
            currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length;
            UI.updateProxyStatus();
        }

        function getProxiedUrl(originalUrl) {
            const proxy = getEffectiveProxyUrl();
            return proxy + encodeURIComponent(originalUrl);
        }

        // ==================== KNOWN QUOTE CURRENCIES ====================
        const KNOWN_QUOTES = [
            'USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY', 'KRW',
            'AUD', 'CAD', 'CHF', 'RUR', 'RUB', 'INR', 'TRY', 'BRL', 'IDR', 'DAI', 'SGD', 'PLN', 'UAH', 'AED',
            'BETH', 'ZEC', 'ZRX', 'RAY', 'STRK', 'MATIC', 'DOT', 'TRB', 'TON', 'PI', 'LTC', 'XRP', 'SHIB',
            'DOGE', 'BONK', 'PEPE', 'FLOKI', 'WIN', 'SATS', 'NEIRO', 'CAT', 'DUCK', 'BOME', 'OMI', 'DEGEN',
            'NOT', 'MEME', 'TOSHI', 'MEW', 'HMSTR', 'XCHNG'
        ];
        KNOWN_QUOTES.sort((a, b) => b.length - a.length);

        function parsePairSymbol(rawSymbol) {
            const sym = (rawSymbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            if (!sym) return null;
            for (const quote of KNOWN_QUOTES) {
                if (sym.endsWith(quote) && sym.length > quote.length) {
                    const base = sym.slice(0, sym.length - quote.length);
                    if (base.length >= 1 && base !== quote) {
                        return { base, target: quote };
                    }
                }
            }
            const parts = sym.split(/[-_/]/);
            if (parts.length >= 2 && parts[0] && parts[1]) {
                return { base: parts[0], target: parts[1] };
            }
            return null;
        }

