            openTradeModal(oppStr) {
                const opp = JSON.parse(decodeURIComponent(oppStr));
                const bet = parseFloat(document.getElementById('betInput').value) || 1000;
                const tradeSize = Math.min(opp.maxTradeSize, bet);
                let runningTotal = tradeSize;
                let mathString = `💰 Start: $${tradeSize.toFixed(2)}<br>`;
                const detailsHtml = opp.edges.map((edge, i) => {
                    const prev = runningTotal;
                    runningTotal *= edge.rate;
                    mathString +=
                        `Hop ${i+1}: $${prev.toFixed(2)} × ${edge.rate.toFixed(6)} → $${runningTotal.toFixed(2)}<br>`;
                    const depthPct = Math.min(1, tradeSize / (edge.liquidity + 1));
                    const depthColor = depthPct > 0.8 ? '#ff4444' : depthPct > 0.5 ? '#ffaa00' :
                        'var(--cyan)';
                    return `<div style="margin:5px 0;padding:8px;background:#111;border-radius:5px;">
                <strong>${opp.path[i]} → ${opp.path[i+1]}</strong> <span class="chip">${edge.exchangeType.toUpperCase()}</span>
                <div class="depth-chart">${Array.from({length:10},(_,j)=>{ const level=(j+1)/10; return `<div class="depth-bar" style="height:${level<=depthPct?25:5}px;background:${level<=depthPct?depthColor:'#333'};"></div>`; }).join('')}</div>
                <div style="font-size:9px;">Liq: $${edge.liquidity.toFixed(0)} | Depth: ${(depthPct*100).toFixed(1)}%</div>
            </div>`;
                }).join('');
                mathString +=
                    `<strong style="color:var(--green);">🏁 Final: $${runningTotal.toFixed(2)}</strong>`;
                document.getElementById('tradeDetails').innerHTML =
                    `<p>🔄 ${opp.path.join(' → ')}</p><p>💰 Trade: $${tradeSize.toFixed(2)}</p>${detailsHtml}`;
                document.getElementById('compoundingMath').innerHTML =
                    `<h4>📐 Compounding (${opp.edges.length} hops)</h4>${mathString}`;
                document.getElementById('executeTradeBtn').onclick = () => {
                    closeModal();
                    Engine.executeTrade(opp, tradeSize, runningTotal - tradeSize);
                };
                document.getElementById('tradeModal').style.display = 'flex';
            },
            closeModal() { document.getElementById('tradeModal').style.display = 'none'; },
            updateSlotDepthLabel() {
                document.getElementById('slotDepthLabel').textContent = document.getElementById('pathInput').value;
            },
            renderFiatCheckboxes() {
                const container = document.getElementById('fiatCheckboxes');
                const allFiats = ['RUR', 'INR', 'EUR', 'GBP', 'RUB', 'JPY', 'CNY', 'KRW', 'AUD', 'CAD', 'CHF',
                'AED'];
                container.innerHTML = '';
                allFiats.forEach(f => {
                    const checked = State.selectedFiats.has(f) ? 'checked' : '';
                    container.innerHTML +=
                        `<label><input type="checkbox" value="${f}" ${checked} onchange="UI.toggleFiat('${f}')"> ${f}</label>`;
                });
            },
            toggleFiat(fiat) {
                State.selectedFiats.has(fiat) ? State.selectedFiats.delete(fiat) : State.selectedFiats.add(
                fiat);
                State.save();
                // auto-fetch if rates not loaded yet
                if (Object.keys(State.forexRates).length === 0 && document.getElementById('scanBtn').disabled ===
                    false) {
                    fetchForexRates();
                }
            },
            onProxyChange() {
                const mode = document.getElementById('proxySelect').value;
                const customInput = document.getElementById('corsProxyUrl');
                if (mode === 'custom') {
                    customInput.style.display = 'inline-block';
                } else {
                    customInput.style.display = 'none';
                }
                State.proxyMode = mode;
                State.save();
                this.updateProxyStatus();
            },
            updateProxyStatus() {
                const msg = document.getElementById('proxyStatusMsg');
                if (State.proxyMode === 'builtin') {
                    msg.innerHTML =
                        `<span class="success-box">✅ Using built‑in proxy (${BUILTIN_PROXIES[currentProxyIndex]}). Fetching directly through public CORS services.</span>`;
                } else {
                    const custom = document.getElementById('corsProxyUrl').value.trim();
                    if (custom && !custom.includes('your-worker') && !custom.includes('placeholder')) {
                        msg.innerHTML =
                            `<span class="success-box">✅ Custom proxy active: ${custom}</span>`;
                    } else {
                        msg.innerHTML =
                            `<span class="warning-box">⚠️ Custom proxy URL is placeholder – falling back to built‑in proxy.</span>`;
                    }
                }
            },
            renderTradeLedger() {
                const el = document.getElementById('tradeLedger');
                if (!el) return;
                if (State.tradeLedger.length === 0) {
                    el.innerHTML = '<div style="color:#666;">No trades executed yet.</div>';
                    return;
                }
                el.innerHTML = State.tradeLedger.map(e =>
                    `<div style="margin:2px 0;">[${new Date(e.time).toLocaleTimeString()}] ${e.type.toUpperCase()} $${e.profit.toFixed(2)} | ${e.path}</div>`
                ).join('');
            }
        };
        function closeModal() { UI.closeModal(); }

        // ==================== FOREX RATES ====================
        async function fetchForexRates() {
            const fiats = [...State.selectedFiats];
            if (fiats.length === 0) { log('No fiat currencies selected.', 'warning'); return; }
            const vs = fiats.join(',');
            const url = `https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd,${vs}`;
            try {
                const resp = await fetch(getProxiedUrl(url));
                const data = await resp.json();
                if (!data.bitcoin) throw new Error('Invalid response');
                const btcUsd = data.bitcoin.usd;
                State.forexRates = {};
                fiats.forEach(f => { if (data.bitcoin[f]) { State.forexRates[f] = btcUsd / data.bitcoin[f]; } });
                State.save();
                document.getElementById('forexStatus').textContent = `Updated: ${Object.keys(State.forexRates).length} rates`;
                log('Forex rates updated via CoinGecko.', 'success');
                displayLowValue();
            } catch (e) {
                log(`Forex fetch failed: ${e.message}`, 'error');
                rotateProxy(); // try next proxy
            }
        }

        function getUsdPrice(pair) {
            if (!pair) return 0;
            if (['USDT', 'USD', 'USDC', 'BUSD', 'GUSD'].includes(pair.target)) return pair.price;
            const rate = State.forexRates[pair.target];
            return rate ? pair.price * rate : pair.price;
        }

        function toUsd(amount, currency) {
            if (!currency || ['USDT', 'USD', 'USDC', 'BUSD', 'GUSD'].includes(currency)) return amount;
            const rate = State.forexRates[currency];
            return rate ? amount * rate : amount;
        }

        // ==================== API LOADERS (with proxy rotation) ====================
        async function loadApi(defKey) {
            const ex = State.exchanges[defKey];
            try {
                let headers = {};
                if (ex.auth) {
                    const token = document.getElementById('pumpToken').value.trim();
                    if (token) headers = { 'Authorization': 'Bearer ' + token };
                }
                const url = getProxiedUrl(ex.url);
                const resp = await fetch(url, { headers });
                if (!resp.ok) throw new Error('HTTP ' + resp.status);
                const data = await resp.json();
                let pairs = [];
                switch (ex.parser) {
                    case 'okx':
                        pairs = (data.data || []).slice(0, 600).map(t => {
                            const parts = t.instId.split('-');
                            if (parts.length !== 2) return null;
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.volCcy24h) || 0) * price;
                            return { base: parts[0], target: parts[1], price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bidPx) || price * 0.999, askPrice: parseFloat(t
                                    .askPx) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(Boolean);
                        break;
                    case 'coinbase':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 300).map(p => {
                            const price = parseFloat(p.price) || 1;
                            const vol = (parseFloat(p.volume) || 0) * price;
                            return { base: p.base_currency, target: p.quote_currency, price, volume: vol,
                                liquidity: vol, bidPrice: price * 0.998, askPrice: price * 1.002, exchange: defKey,
                                exchangeType: ex.type };
                        }).filter(p => p.price > 0);
                        break;
                    case 'binance':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 600).map(t => {
                            const price = parseFloat(t.lastPrice) || 0,
                                vol = (parseFloat(t.quoteVolume) || 0) * price;
                            const sym = t.symbol || '';
                            const parsed = parsePairSymbol(sym);
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bidPrice) || price * 0.999, askPrice: parseFloat(t
                                    .askPrice) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base && p.base !== p.target);
                        break;
                    case 'kucoin':
                        pairs = (data?.data?.ticker || []).slice(0, 500).map(t => {
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.volValue) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol,
                            liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(
                                    t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base);
                        break;
                    case 'bybit':
                        pairs = (data?.result?.list || []).slice(0, 400).map(t => {
                            const price = parseFloat(t.lastPrice) || 0,
                                vol = (parseFloat(t.volume24h) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bid1Price) || price * 0.999, askPrice: parseFloat(t
                                    .ask1Price) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'gate':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.quote_volume) || 0) * price;
                            const parsed = parsePairSymbol(t.currency_pair || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.highest_bid) || price * 0.999, askPrice: parseFloat(t
                                    .lowest_ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base);
                        break;
                    case 'mexc':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.lastPrice) || 0,
                                vol = (parseFloat(t.quoteVolume) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bidPrice) || price * 0.999, askPrice: parseFloat(t
                                    .askPrice) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'kraken': {
                        const result = data?.result || {};
                        pairs = Object.keys(result).slice(0, 300).map(k => {
                            const t = result[k];
                            const price = parseFloat(t.c?.[0]) || 0,
                                vol = (parseFloat(t.v?.[1]) || 0) * price;
                            const parsed = parsePairSymbol(k);
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol,
                            liquidity: vol, bidPrice: parseFloat(t.b?.[0]) || price * 0.999, askPrice: parseFloat(
                                    t.a?.[0]) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'bitstamp':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 250).map(t => {
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.volume) || 0) * price;
                            const parts = (t.pair || '').split('/');
                            return { base: parts[0] || '', target: parts[1] || 'USD', price, volume: vol,
                                liquidity: vol, bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(
                                    t.ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p.price > 0 && p.base);
                        break;
                    case 'indodax': {
                        const tickers = data || {};
                        pairs = Object.keys(tickers).slice(0, 250).map(k => {
                            const t = tickers[k];
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.vol_idr) || 0) * price;
                            const parsed = parsePairSymbol(k);
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol,
                            liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(
                                    t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'yobit': {
                        const info = data?.pairs || {};
                        const allKeys = Object.keys(info).slice(0, 200);
                        if (allKeys.length === 0) throw new Error('No pairs');
                        const tickerUrl = getProxiedUrl(`https://yobit.net/api/3/ticker/${allKeys.join('-')}`);
                        const tickerResp = await fetch(tickerUrl);
                        const tickerData = await tickerResp.json();
                        pairs = allKeys.map(k => {
                            const t = tickerData[k] || {};
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.vol) || 0) * price;
                            const parsed = parsePairSymbol(k);
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol,
                            liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(
                                    t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'gemini': {
                        const arr = Array.isArray(data) ? data : [];
                        pairs = arr.map(t => {
                            const rawPair = t.pair || t.symbol || '';
                            const parsed = parsePairSymbol(rawPair);
                            if (!parsed) return null;
                            const price = parseFloat(t.price) || 0;
                            return { base: parsed.base, target: parsed.target, price, volume: 0, liquidity: price *
                                    100000, bidPrice: price * 0.998, askPrice: price * 1.002, exchange: defKey,
                                exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base && p.base !== p.target && p.liquidity >= 50);
                        log(`Gemini parsed: ${pairs.length} valid pairs`, 'success');
                        break;
                    }
                    case 'pumpfun':
                        pairs = (Array.isArray(data) ? data : []).map(t => {
                            const price = parseFloat(t.usd_market_cap) / parseFloat(t.total_supply) || 0;
                            const liq = parseFloat(t.usd_market_cap) * 0.1 || 0;
                            return { base: t.symbol || 'UNKNOWN', target: 'SOL', price, volume: liq * 0.5,
                                liquidity: liq, bidPrice: price * 0.95, askPrice: price * 1.05, exchange: defKey,
                                exchangeType: 'cex' };
                        }).filter(p => p.base !== 'UNKNOWN' && p.price > 0);
                        if (pairs.length === 0) throw new Error('Empty');
                        break;
                    case 'poloniex':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.close) || 0,
                                vol = (parseFloat(t.quantity) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(t.ask) || price *
                                1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'huobi':
                        pairs = (data?.data || []).slice(0, 400).map(t => {
                            const price = parseFloat(t.close) || 0,
                                vol = (parseFloat(t.vol) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(t.ask) || price *
                                1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'ascendex':
                        pairs = (data?.data || []).slice(0, 250).map(t => {
                            const price = parseFloat(t.close) || 0,
                                vol = (parseFloat(t.volume) || 0) * price;
                            const parts = (t.symbol || '').split('/');
                            return { base: parts[0] || '', target: parts[1] || 'USDT', price, volume: vol,
                                liquidity: vol, bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(
                                    t.ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p.price > 0);
                        break;
                    case 'digifinex':
                        pairs = (data?.ticker || []).slice(0, 250).map(t => {
                            const price = parseFloat(t.last) || 0,
                                vol = (parseFloat(t.base_volume) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(t.sell) || price *
                                1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'bittrex':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 250).map(t => {
                            const price = parseFloat(t.lastTradeRate) || 0;
                            const parsed = parsePairSymbol(t.symbol || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: 0, liquidity: 0,
                                bidPrice: price * 0.999, askPrice: price * 1.001, exchange: defKey,
                            exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'cryptocom':
                        pairs = (data?.result?.data || []).slice(0, 250).map(t => {
                            const price = parseFloat(t.a) || 0,
                                vol = (parseFloat(t.v) || 0) * price;
                            const parsed = parsePairSymbol(t.i || '');
                            if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol,
                                bidPrice: parseFloat(t.b) || price * 0.999, askPrice: parseFloat(t.k) || price * 1.001,
                                exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'dexscreener': {
                        const raw = data?.pairs || [];
                        pairs = raw.slice(0, 400).map(p => {
                            const price = parseFloat(p.priceUsd) || 0,
                                liq = p.liquidity?.usd || 0,
                                vol = p.volume?.h24 || 0;
                            const spread = liq > 0 ? Math.max(0.003, Math.min(0.05, 5000 / liq)) : 0.03;
                            return { base: p.baseToken?.symbol || 'UNKNOWN', target: p.quoteToken?.symbol ||
                                    'ETH', price, volume: vol, liquidity: liq, bidPrice: price * (1 - spread / 2),
                                askPrice: price * (1 + spread / 2), exchange: defKey, exchangeType: 'dex' };
                        }).filter(p => p.base !== 'UNKNOWN' && p.price > 0);
                        break;
                    }
                    case 'coingecko': {
                        const cg = Array.isArray(data) ? data : [];
                        pairs = cg.slice(0, 250).map(c => ({ base: (c.symbol || '').toUpperCase(), target: 'USD',
                            price: c.current_price || 0, volume: c.total_volume || 0, liquidity: c.market_cap || 0,
                            bidPrice: (c.current_price || 0) * 0.999, askPrice: (c.current_price || 0) * 1.001,
                            exchange: defKey, exchangeType: 'info' })).filter(p => p.price > 0);
                        break;
                    }
                    case 'coinlore': {
                        const cl = data?.data || [];
                        pairs = cl.slice(0, 250).map(c => ({ base: c.symbol || '', target: 'USD', price: parseFloat(c
                                .price_usd) || 0, volume: parseFloat(c.volume24) || 0, liquidity: parseFloat(c
                                .market_cap_usd) || 0, bidPrice: (parseFloat(c.price_usd) || 0) * 0.999,
                            askPrice: (parseFloat(c.price_usd) || 0) * 1.001, exchange: defKey, exchangeType: 'info' }))
                            .filter(p => p.price > 0);
                        break;
                    }
                    case 'coinpaprika': {
                        const cp = Array.isArray(data) ? data : [];
                        pairs = cp.slice(0, 250).map(t => ({ base: t.symbol || '', target: 'USD', price: parseFloat(t
                                .quotes?.USD?.price) || 0, volume: parseFloat(t.quotes?.USD?.volume_24h) || 0,
                            liquidity: parseFloat(t.quotes?.USD?.market_cap) || 0, bidPrice: (parseFloat(t.quotes
                                ?.USD?.price) || 0) * 0.999, askPrice: (parseFloat(t.quotes?.USD?.price) || 0) *
                                1.001, exchange: defKey, exchangeType: 'info' })).filter(p => p.price > 0);
                        break;
                    }
                    case 'coincap': {
                        const assets = data?.data || [];
                        pairs = assets.slice(0, 100).map(a => ({ base: a.symbol || a.id, target: 'USD',
                            price: parseFloat(a.priceUsd) || 0, volume: parseFloat(a.volumeUsd24Hr) || 0,
                            liquidity: parseFloat(a.marketCapUsd) || 0, bidPrice: (parseFloat(a.priceUsd) || 0) *
                                0.999, askPrice: (parseFloat(a.priceUsd) || 0) * 1.001, exchange: defKey,
                            exchangeType: 'info' })).filter(p => p.price > 0);
                        break;
                    }
                    default:
                        pairs = [];
                }
                pairs = pairs.filter(p => p && p.base && p.target && p.base !== p.target && p.price > 0 && p.price <
                    1e15);
                ex.pairs = pairs;
                ex.status = 'online';
                log(`${ex.name}: ${ex.pairs.length} pairs`, 'success');
            } catch (e) {
                if (defKey === 'pumpfun') {
                    log('Pump.fun direct failed, trying fallback...', 'warning');
                    try {
                        const fbResp = await fetch(getProxiedUrl(
                            'https://api.dexscreener.com/latest/dex/search?q=SOL'));
                        const fbData = await fbResp.json();
                        const fbPairs = (fbData?.pairs || []).slice(0, 400).map(p => {
                            const price = parseFloat(p.priceUsd) || 0,
                                liq = p.liquidity?.usd || 0;
                            const spread = liq > 0 ? Math.max(0.003, Math.min(0.05, 5000 / liq)) : 0.03;
                            return { base: p.baseToken?.symbol || 'UNKNOWN', target: p.quoteToken?.symbol ||
                                    'ETH', price, volume: p.volume?.h24 || 0, liquidity: liq, bidPrice: price *
                                    (1 - spread / 2), askPrice: price * (1 + spread / 2),
                                exchange: 'pumpfun_fallback', exchangeType: 'dex' };
                        }).filter(p => p.base !== 'UNKNOWN' && p.price > 0);
                        ex.pairs = fbPairs;
                        ex.status = 'online';
                        log(`Pump.fun fallback: ${ex.pairs.length} pairs`, 'success');
                        return;
                    } catch (fbErr) { log(`Fallback also failed: ${fbErr.message}`, 'error'); }
                }
                ex.status = 'offline';
                ex.pairs = [];
                log(`${ex.name}: ${e.message}`, 'error');
                rotateProxy(); // try next proxy on failure
            }
        }

        // ==================== INIT ====================
        async function initSystem() {
            log('🎰 Initializing all exchanges (with auto proxy)...');
            updateStatus('🔄 LOADING...');
            playSpin();
            UI.updateProxyStatus();
            await Promise.allSettled(exchangeDefs.map(d => loadApi(d.key)));
            State.allPairs = Object.values(State.exchanges).flatMap(e => e.pairs);
            State.userCoins.forEach(c => {
                State.allPairs.push({ base: c.symbol, target: 'USDT', price: c.price, volume: c.liq * 0.3,
                    liquidity: c.liq, bidPrice: c.price * 0.95, askPrice: c.price * 1.05, exchange: 'QUANTM_DEX',
                    exchangeType: 'dex' });
            });
            State.stats.totalPairs = State.allPairs.length;
            updateIntraExCheckboxes();
            buildGraph();
            buildTriangles();
            displayLowValue();
            updateExchangeDisplay();
            updateStats();
            const online = Object.values(State.exchanges).filter(e => e.status === 'online').length;
            if (online > 0) {
                document.getElementById('scanBtn').disabled = false;
                updateStatus(`✅ READY · ${online}/${exchangeDefs.length} online · ${State.stats.totalPairs} pairs`);
                log('System ready.', 'success');
            } else { updateStatus('❌ NO EXCHANGES ONLINE'); }
            // Auto-fetch forex if none loaded
            if (Object.keys(State.forexRates).length === 0 && State.selectedFiats.size > 0) {
                log('No forex rates found, auto‑fetching...');
